const { Worker, isMainThread, parentPort } = require('worker_threads');

if (isMainThread) {
  // --- MAIN THREAD (The Manager) ---
  console.log("Main: I have a heavy math job.");

  // 1. Create the worker (pointing it at this same file)
  const worker = new Worker(__filename);

  // 2. Listen for the result
  worker.on('message', (result) => {
    console.log(`Main: The worker finished! Result: ${result}`);
  });

  // 3. Send data to the worker to start
  worker.postMessage(1000000000);

  console.log("Main: I am completely unblocked and can handle HTTP requests while the worker does the math!");

} else {
  // --- BACKGROUND WORKER (The Chef) ---
  // 4. Listen for instructions from the Main thread
  parentPort.on('message', (limit) => {

    // 5. Do the heavy math (This would freeze a normal Node app!)
    let count = 0;
    for (let i = 0; i < limit; i++) {
      count++;
    }

    // 6. Send the result back to Main
    parentPort.postMessage(count);
  });
}
